from __future__ import annotations

import html
from typing import IO

from secretscan.model import Finding, Module, RunMeta

_SEVERITY_COLORS = {
    "critical": "#e74c3c",
    "high": "#e67e22",
    "medium": "#f39c12",
    "low": "#95a5a6",
}


def _categorize(findings: list[Finding]) -> dict[str, list[Finding]]:
    cats: dict[str, list[Finding]] = {
        "regular": [], "private_keys": [], "keychain": [],
        "process_env": [], "placeholders": [],
    }
    for f in findings:
        if f.file_identity:
            cats["private_keys"].append(f)
        elif f.module == Module.KEYCHAIN:
            cats["keychain"].append(f)
        elif f.module == Module.PROCESS_ENV:
            cats["process_env"].append(f)
        elif f.placeholder:
            cats["placeholders"].append(f)
        else:
            cats["regular"].append(f)
    return cats


def _esc(s: str) -> str:
    return html.escape(s)


def _findings_table(findings: list[Finding], title: str) -> str:
    if not findings:
        return ""
    rows = ""
    for f in findings:
        color = _SEVERITY_COLORS.get(f.severity.value, "#95a5a6")
        extra = f" <span class='extra'>(+{len(f.additional_files)} more)</span>" if f.additional_files else ""
        rows += f"""<tr>
<td><span class="sev" style="background:{color}">{_esc(f.severity.value.upper())}</span></td>
<td>{_esc(f.rule_id)}</td>
<td class="loc">{_esc(f.location)}{extra}</td>
<td class="val"><code>{_esc(f.redacted_value)}</code></td>
<td class="fp">{_esc(f.fingerprint)}</td>
</tr>"""
    return f"""<h2>{_esc(title)} ({len(findings)})</h2>
<table><thead><tr><th>SEV</th><th>RULE</th><th>LOCATION</th><th>VALUE</th><th>FINGERPRINT</th></tr></thead>
<tbody>{rows}</tbody></table>"""


def render_html(w: IO[str], findings: list[Finding], meta: RunMeta) -> None:
    cats = _categorize(findings)

    elapsed = ""
    if meta.started_at and meta.finished_at:
        elapsed = f"{(meta.finished_at - meta.started_at).total_seconds():.1f}s"

    severity_summary = ""
    for sev in ("critical", "high", "medium", "low"):
        count = meta.severity_counts.get(sev, 0)
        if count:
            color = _SEVERITY_COLORS.get(sev, "#95a5a6")
            severity_summary += f'<span class="sev" style="background:{color}">{sev}: {count}</span> '

    module_rows = ""
    for st in meta.module_statuses:
        module_rows += f"<tr><td>{_esc(st.module.value)}</td><td>{st.accessed}/{st.attempted}</td><td>{_esc(st.note[:100])}</td></tr>"

    listeners_html = ""
    if meta.listeners:
        lrows = ""
        for l in meta.listeners:
            exp_class = "exposed" if l.exposure == "all interfaces" else ""
            lrows += f"<tr class='{exp_class}'><td>{_esc(l.proto)}</td><td>{_esc(l.address)}:{_esc(l.port)}</td><td>{_esc(l.process_name)}</td><td>{_esc(l.pid)}</td><td>{_esc(l.exposure)}</td></tr>"
        listeners_html = f"""<h2>Listening Ports ({len(meta.listeners)})</h2>
<table><thead><tr><th>PROTO</th><th>ADDRESS</th><th>PROCESS</th><th>PID</th><th>EXPOSURE</th></tr></thead>
<tbody>{lrows}</tbody></table>"""

    tools_html = ""
    if meta.tools:
        curated = [t for t in meta.tools if t.curated]
        if curated:
            trows = ""
            for t in curated:
                trows += f"<tr><td>{_esc(t.name)}</td><td>{_esc(t.version[:80])}</td><td>{_esc(t.source)}</td></tr>"
            tools_html = f"""<h2>Installed Tools ({len(curated)} curated)</h2>
<table><thead><tr><th>NAME</th><th>VERSION</th><th>SOURCE</th></tr></thead>
<tbody>{trows}</tbody></table>"""

    docker_html = ""
    if meta.docker:
        d = meta.docker
        api_warn = '<p class="warn">WARNING: Docker Engine API exposed on localhost:2375!</p>' if d.api_exposed else ""
        crows = ""
        for c in d.containers:
            exp = "EXPOSED" if c.exposed else "local"
            crows += f"<tr><td>{_esc(c.name)}</td><td>{_esc(c.image)}</td><td>{exp}</td><td>{_esc(', '.join(c.ports))}</td></tr>"
        containers_table = ""
        if crows:
            containers_table = f"<table><thead><tr><th>NAME</th><th>IMAGE</th><th>EXPOSURE</th><th>PORTS</th></tr></thead><tbody>{crows}</tbody></table>"
        docker_html = f"""<h2>Docker</h2>
<p>Installed: {d.installed} | Daemon: {d.daemon_running}</p>
{api_warn}{containers_table}"""

    internet_html = ""
    if meta.internet:
        ip_line = f"<p>Public IP: {_esc(meta.internet.public_ip)}</p>" if meta.internet.public_ip else ""
        irows = ""
        for chk in meta.internet.checks:
            icon = "&#10003;" if chk.reachable else "&#10007;"
            cls = "ok" if chk.reachable else "fail"
            irows += f"<tr class='{cls}'><td>{icon}</td><td>{_esc(chk.name)}</td><td>{_esc(chk.host)}:{chk.port}</td></tr>"
        internet_html = f"""<h2>Internet Connectivity</h2>
{ip_line}
<table><thead><tr><th></th><th>SERVICE</th><th>ENDPOINT</th></tr></thead>
<tbody>{irows}</tbody></table>"""

    chrome_html = ""
    if meta.chrome and meta.chrome.installed:
        ch = meta.chrome
        chrome_html = f'<h2>Chrome Browser</h2>\n<div class="meta">'
        chrome_html += f"<p><strong>Binary:</strong> {_esc(ch.binary_path)}</p>"
        chrome_html += f"<p><strong>Version:</strong> {_esc(ch.version)}</p>"
        chrome_html += f"<p><strong>User Data:</strong> {_esc(ch.user_data_dir)}</p>"
        if ch.error:
            chrome_html += f'<p class="warn">{_esc(ch.error)}</p>'
        chrome_html += "</div>"
        for cp in ch.profiles:
            chrome_html += f"<h3>Profile: {_esc(cp.display_name)} ({_esc(cp.dir_name)})</h3>"
            launched_str = "launched headless" if cp.launched else "not launched"
            chrome_html += f"<p>{launched_str} | {len(cp.cookies)} cookies"
            if cp.screenshot_bytes:
                chrome_html += f" | screenshot {cp.screenshot_bytes:,} bytes"
            chrome_html += "</p>"
            if cp.error:
                chrome_html += f'<p class="warn">{_esc(cp.error)}</p>'
            if cp.cookies:
                by_domain: dict[str, int] = {}
                for ck in cp.cookies:
                    by_domain[ck.domain] = by_domain.get(ck.domain, 0) + 1
                top = sorted(by_domain.items(), key=lambda x: -x[1])[:20]
                crows = ""
                for domain, count in top:
                    crows += f"<tr><td>{_esc(domain)}</td><td>{count}</td></tr>"
                chrome_html += (
                    '<table><thead><tr><th>DOMAIN</th><th>COOKIES</th></tr></thead>'
                    f'<tbody>{crows}</tbody></table>'
                )

    lan_html = ""
    if meta.lan_devices:
        drows = ""
        for dev in meta.lan_devices:
            drows += f"<tr><td>{_esc(dev.ip)}</td><td>{_esc(dev.mac)}</td><td>{_esc(dev.hostname)}</td></tr>"
        lan_html = f"""<h2>Local Network Devices ({len(meta.lan_devices)})</h2>
<table><thead><tr><th>IP</th><th>MAC</th><th>HOSTNAME</th></tr></thead>
<tbody>{drows}</tbody></table>"""

    w.write(f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>secretscan report</title>
<style>
:root {{
  --bg: #0d1117; --fg: #c9d1d9; --card: #161b22; --border: #30363d;
  --accent: #58a6ff; --muted: #8b949e;
}}
@media (prefers-color-scheme: light) {{
  :root {{ --bg: #fff; --fg: #24292f; --card: #f6f8fa; --border: #d0d7de; --accent: #0969da; --muted: #656d76; }}
}}
* {{ margin: 0; padding: 0; box-sizing: border-box; }}
body {{ font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
  background: var(--bg); color: var(--fg); line-height: 1.6; padding: 2rem; max-width: 1200px; margin: 0 auto; }}
h1 {{ font-size: 1.5rem; margin-bottom: 0.5rem; }}
h2 {{ font-size: 1.1rem; margin: 2rem 0 0.5rem; border-bottom: 1px solid var(--border); padding-bottom: 0.25rem; }}
.meta {{ background: var(--card); border: 1px solid var(--border); border-radius: 6px; padding: 1rem; margin: 1rem 0; font-size: 0.85rem; }}
.meta p {{ margin: 0.15rem 0; }}
.sev {{ display: inline-block; padding: 1px 8px; border-radius: 3px; color: #fff; font-size: 0.75rem; font-weight: 600; }}
table {{ width: 100%; border-collapse: collapse; font-size: 0.82rem; margin-bottom: 1rem; }}
th {{ text-align: left; padding: 6px 8px; background: var(--card); border-bottom: 2px solid var(--border); font-weight: 600; }}
td {{ padding: 5px 8px; border-bottom: 1px solid var(--border); vertical-align: top; }}
tr:hover {{ background: var(--card); }}
.loc {{ max-width: 300px; word-break: break-all; }}
.val code {{ background: var(--card); padding: 1px 4px; border-radius: 3px; font-size: 0.8rem; }}
.fp {{ color: var(--muted); font-family: monospace; font-size: 0.75rem; }}
.extra {{ color: var(--muted); font-size: 0.8rem; }}
.warn {{ color: #e74c3c; font-weight: 600; }}
.exposed td {{ background: rgba(231,76,60,0.08); }}
.fail td {{ color: #e74c3c; }}
.ok td:first-child {{ color: #2ecc71; }}
</style>
</head>
<body>
<h1>secretscan report</h1>
<div class="meta">
<p><strong>Host:</strong> {_esc(meta.hostname)}</p>
<p><strong>Scanned:</strong> {_esc(', '.join(meta.paths))}</p>
<p><strong>Modules:</strong> {_esc(', '.join(m.value for m in meta.modules))}</p>
<p><strong>Duration:</strong> {elapsed}</p>
<p>{severity_summary}</p>
</div>

{_findings_table(cats["regular"], "Findings")}
{_findings_table(cats["private_keys"], "Private Keys")}
{_findings_table(cats["keychain"], "Keychain Items")}
{_findings_table(cats["process_env"], "Running Processes")}
{listeners_html}
{tools_html}
{docker_html}
{chrome_html}
{internet_html}
{lan_html}
{_findings_table(cats["placeholders"], "Likely Placeholders")}

<div class="meta">
<h2>Module Status</h2>
<table><thead><tr><th>MODULE</th><th>ACCESSED</th><th>NOTE</th></tr></thead>
<tbody>{module_rows}</tbody></table>
</div>

<p style="text-align:center; color:var(--muted); margin-top:2rem; font-size:0.8rem;">
Generated by secretscan v0.1.0
</p>
</body>
</html>
""")
